/**
 * The generated icon set, read as source — F726.
 *
 * Founder decision D11: one family of icons, Iconsax free icons plus a few of
 * Luvani's own, generated by `npm run icons` into react-native-svg components
 * at the app's one stroke. There is no renderer in this workspace
 * (docs/TESTING.md), so the promises are read off the files: each icon is
 * decorative, coloured only by the tokens its caller passes, drawn at the one
 * pen, and exactly what `scripts/icons/icons.config.mjs` makes from the pinned
 * package, so a hand edit or a stale file fails here as `npm run icons --
 * --check` would.
 *
 * Nothing here imports a component: the drawings need react-native-svg, which
 * Node cannot load. Only the pure modules (the config, the cleaner, the names
 * and the place map) are imported.
 */

import { describe, test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { ICON_CONFIG, ICONSAX_VERSION } from '../../../../scripts/icons/icons.config.mjs';
import { clean, parseSvg, pascal, toTsx } from '../../../../scripts/icons/svg.mjs';
import { ICON_NAMES } from './names.ts';

const HERE = fileURLToPath(new URL('.', import.meta.url));
const SRC = join(HERE, '..');
const ROOT = join(SRC, '..', '..', '..');
const CUSTOM = join(ROOT, 'scripts', 'icons', 'custom');
const GENERATED_HEADER = '// Generated by scripts/icons/build-icons.mjs';

/** Comments may say anything; only what reaches glass is under test. */
function stripComments(source: string): string {
  const noBlocks = source.replace(/\/\*[\s\S]*?\*\//g, (m) => m.replace(/[^\n]/g, ' '));
  return noBlocks.replace(/(^|[^:])\/\/.*$/gm, (_m, keep: string) => keep);
}

const CONFIG = Object.entries(ICON_CONFIG);
const generatedFiles = () =>
  readdirSync(HERE)
    .filter((file) => file.endsWith('.tsx'))
    .map((file) => ({ file, raw: readFileSync(join(HERE, file), 'utf8') }))
    .filter(({ raw }) => raw.startsWith(GENERATED_HEADER));

function walk(dir: string, out: string[] = []): string[] {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) walk(full, out);
    else out.push(full);
  }
  return out;
}

describe('the icon set — F726', () => {
  test('every generated icon is decorative, token-coloured and drawn at the one stroke', () => {
    const files = generatedFiles();
    assert.equal(files.length, CONFIG.length, `${files.length} generated icon files for ${CONFIG.length} icons in the config`);
    assert.ok(files.length >= 90, `only ${files.length} icons were generated, so this walk reads almost nothing`);

    for (const [name, spec] of CONFIG) {
      const component = pascal(name);
      const path = join(HERE, `${component}.tsx`);
      assert.ok(existsSync(path), `${name} has no generated icons/${component}.tsx`);
      const body = stripComments(readFileSync(path, 'utf8'));
      const where = `icons/${component}.tsx`;

      // One export, the drawings the config asks for, and nothing else.
      assert.match(body, new RegExp(`export const ${component}: IconDrawings = \\{`), `${where} does not export ${component}`);
      assert.match(body, /\n {2}linear: \(\{ size/, `${where} has no Linear drawing`);
      assert.equal(/\n {2}bulk: \(\{ size/.test(body), spec.variants.includes('bulk'), `${where} draws a Bulk icon the config does not ask for, or lacks one it does`);

      // Decorative, on the 24 box, at the size it is handed.
      const svgs = body.match(/<Svg\b[^>]*>/g) ?? [];
      assert.ok(svgs.length > 0, `${where} draws no Svg`);
      for (const tag of svgs) {
        assert.equal(tag, '<Svg width={size} height={size} viewBox="0 0 24 24" {...decorative}>', `${where} draws an Svg that is not the decorative 24 box: ${tag}`);
      }

      // Token-coloured: the caller's colour, the Bulk second layer, or nothing.
      for (const paint of body.match(/\b(?:fill|stroke)=(?:\{[^}]*\}|"[^"]*")/g) ?? []) {
        assert.ok(
          ['fill={color}', 'fill={secondary}', 'fill="none"', 'stroke={color}', 'stroke={secondary}'].includes(paint),
          `${where} paints with something other than the caller's colours: ${paint}`,
        );
      }
      for (const opacity of body.match(/\bopacity=(?:\{[^}]*\}|"[^"]*")/g) ?? []) {
        assert.equal(opacity, 'opacity={SECONDARY_OPACITY}', `${where} sets an opacity of its own: ${opacity}`);
      }
      assert.doesNotMatch(body, /#[0-9a-fA-F]{3,8}\b|rgba?\(|url\(|Gradient|Filter|Mask|Image|Text\b/, `${where} carries a raw colour, a url(), an effect, an image or words`);

      // The one stroke: every weight is STROKE, and every mark that strokes says so.
      for (const weight of body.match(/strokeWidth=\{[^}]*\}/g) ?? []) {
        assert.equal(weight, 'strokeWidth={STROKE}', `${where} writes its own stroke weight: ${weight}`);
      }
      for (const tag of body.match(/<(?!Svg|G\b)\w+ [^>]*\bstroke=\{\w+\}[^>]*>/g) ?? []) {
        assert.ok(tag.includes('strokeWidth={STROKE}'), `${where} strokes a mark at the SVG default weight: ${tag.slice(0, 80)}`);
      }

      // Still: a drawing moves nothing; AnimatedIcon moves a whole drawing around.
      assert.doesNotMatch(body, /Animated|useEffect|useState|interpolate|react-native-reanimated/, `${where} moves`);
    }

    // The names a screen may ask for are exactly the config's.
    assert.deepEqual([...ICON_NAMES], CONFIG.map(([name]) => name), 'names.ts is not the config, so a name is missing or stale');
    const names = readFileSync(join(HERE, 'names.ts'), 'utf8');
    const bulk = CONFIG.filter(([, spec]) => spec.variants.includes('bulk')).map(([name]) => name);
    const bulkUnion = names.slice(names.indexOf('export type BulkIconName'), names.indexOf(';', names.indexOf('export type BulkIconName')));
    assert.deepEqual([...bulkUnion.matchAll(/'([a-z0-9-]+)'/g)].map((m) => m[1]), bulk, 'BulkIconName is not the icons with a Bulk drawing');

    // The registry has every icon, and only Icon.tsx reads it.
    const index = readFileSync(join(HERE, 'index.ts'), 'utf8');
    for (const [name] of CONFIG) {
      assert.ok(index.includes(`import { ${pascal(name)} } from './${pascal(name)}.tsx';`), `index.ts does not import ${pascal(name)}`);
      assert.ok(index.includes(`  '${name}': ${pascal(name)},`), `index.ts does not register ${name}`);
    }
    const readers = walk(SRC)
      .filter((path) => /\.tsx?$/.test(path) && !/\.test\.tsx?$/.test(path))
      .map((path) => ({ short: relative(SRC, path).split(sep).join('/'), body: stripComments(readFileSync(path, 'utf8')) }))
      .filter(({ short, body }) => (short.startsWith('icons/') ? /from '\.\/index\.ts'/ : /from '(?:\.\.\/)*(?:\.\/)?icons\/index\.ts'/).test(body))
      .map(({ short }) => short);
    assert.deepEqual(readers, ['icons/Icon.tsx'], 'something other than Icon.tsx reads the registry');

    // The licence forbids loose Iconsax files: no SVG anywhere in the app, and
    // the custom folder holds only Luvani's own drawings, each one the config uses.
    const svgsInApp = walk(SRC).filter((path) => path.toLowerCase().endsWith('.svg'));
    assert.deepEqual(svgsInApp, [], 'an SVG file is committed in the app');
    const own = new Set(
      CONFIG.filter(([, spec]) => spec.source === 'luvani').flatMap(([, spec]) =>
        spec.variants.map((variant) => (variant === 'linear' ? `${spec.from}.svg` : `${spec.from}.${variant}.svg`)),
      ),
    );
    assert.deepEqual(readdirSync(CUSTOM).sort(), [...own].sort(), 'scripts/icons/custom holds a drawing the config does not name, so it may be a loose third-party icon');
  });

  test('the generated icon set is exactly what icons.config.mjs makes from the pinned package', () => {
    // `npm run icons -- --check`, in-process: every icon is re-made from its
    // source and compared with the file on disk, so a hand edit, a stale file
    // or a moved package version fails here before it reaches a phone.
    const require = createRequire(import.meta.url);
    const manifestPath = require.resolve('iconsax/manifest.json');
    const pkg = JSON.parse(readFileSync(join(dirname(manifestPath), '..', 'package.json'), 'utf8')) as { version: string };
    assert.equal(pkg.version, ICONSAX_VERSION, `iconsax ${pkg.version} is installed and the set is pinned to ${ICONSAX_VERSION}`);
    const manifest = JSON.parse(readFileSync(manifestPath, 'utf8')) as Record<string, { category: string }>;
    const categories = new Map<string, Record<string, Record<string, string>>>();
    const raw = (from: string, variant: string, source: string): string => {
      if (source === 'luvani') return readFileSync(join(CUSTOM, variant === 'linear' ? `${from}.svg` : `${from}.${variant}.svg`), 'utf8');
      const category = manifest[from]?.category;
      assert.ok(category, `iconsax has no ${from}`);
      if (!categories.has(category)) categories.set(category, JSON.parse(readFileSync(join(dirname(manifestPath), 'data', `${category}.json`), 'utf8')));
      const svg = categories.get(category)?.[from]?.[variant];
      assert.ok(svg, `iconsax ${from} has no ${variant} drawing`);
      return svg;
    };
    for (const [name, spec] of CONFIG) {
      const drawings: Record<string, ReturnType<typeof clean>> = {};
      for (const variant of spec.variants) {
        drawings[variant] = clean(parseSvg(raw(spec.from, variant, spec.source), name), name, {
          rotate: spec.rotate,
          translate: spec.translate?.[variant],
          parts: spec.parts?.[variant],
        });
      }
      const header =
        spec.source === 'iconsax'
          ? `${GENERATED_HEADER} from iconsax@${ICONSAX_VERSION} (${spec.from}). Do not edit by hand. Iconsax icon used inside Luvani's source under the Iconsax free licence (https://docs.iconsax.io/license-and-terms/license); not for redistribution as loose icon files.`
          : `${GENERATED_HEADER} from scripts/icons/custom/${spec.from}.svg. Do not edit by hand. Luvani original.`;
      const expected = toTsx({ name, header, drawings });
      assert.equal(readFileSync(join(HERE, `${pascal(name)}.tsx`), 'utf8'), expected, `icons/${pascal(name)}.tsx is not what the config makes; run npm run icons`);
    }
  });

  test('every part AnimatedIcon moves exists, and nothing on the safety stop celebrates', () => {
    const animated = stripComments(readFileSync(join(HERE, 'AnimatedIcon.tsx'), 'utf8'));
    // A part asked for with a literal variant must exist on that drawing; one
    // asked for with `variant={variant}` must exist on both.
    const asked = [...animated.matchAll(/<IconPart name="([a-z-]+)" variant=(?:"(linear|bulk)"|\{variant\}) part="(\w+)"/g)];
    assert.ok(asked.length >= 9, 'AnimatedIcon asks for almost no parts, so this check reads nothing');
    assert.equal(asked.length, (animated.match(/<IconPart\b/g) ?? []).length, 'AnimatedIcon asks for a part in a shape this check cannot read');
    for (const [, name, variant, part] of asked) {
      for (const v of variant === undefined ? (['linear', 'bulk'] as const) : [variant as 'linear' | 'bulk']) {
        const parts = ICON_CONFIG[name!]?.parts?.[v];
        assert.ok(parts && Object.hasOwn(parts, part!), `AnimatedIcon moves ${name} ${v} ${part}, which the config does not split out`);
      }
    }
    // The speaker's arcs breathe on both drawings, so both are split.
    for (const variant of ['linear', 'bulk'] as const) {
      assert.deepEqual(Object.keys(ICON_CONFIG.speaker?.parts?.[variant] ?? {}).sort(), ['arc1', 'arc2', 'body'], `the ${variant} speaker is not split into its body and two arcs`);
    }
    for (const [, name] of animated.matchAll(/<Icon name="([a-z-]+)"/g)) {
      assert.ok((ICON_NAMES as readonly string[]).includes(name!), `AnimatedIcon draws ${name}, which is not in the set`);
    }
    // F137: a safety stop gets no celebration.
    const safety = readFileSync(join(SRC, 'tutor', 'SafetyStopView.tsx'), 'utf8');
    assert.doesNotMatch(safety, /AnimatedIcon/, 'an animated icon plays on the safety stop');
    // Decorative, and silent: the caller that owns the event gives the haptic or the sound.
    assert.match(animated, /<View \{\.\.\.decorative\} pointerEvents="none" style=\{\{ width: size, height: size \}\}>/, 'AnimatedIcon is not decorative');
    assert.doesNotMatch(animated, /haptics|sound\/|playSfx|celebrate\(/, 'AnimatedIcon fires a haptic or a sound of its own');
  });

  test('a tile pairs each ground with the one mark colour that may sit on it', () => {
    const tile = stripComments(readFileSync(join(HERE, 'IconTile.tsx'), 'utf8')).replace(/\s+/g, ' ');
    for (const [ground, fill, mark] of [
      ['blue', 'colour.blue', 'paper.onInk'],
      ['coral', 'colour.coral', 'paper.onInk'],
      ['sun', 'colour.sun', 'paper.ink'],
      ['mint', 'colour.mint', 'paper.ink'],
      ['ink', 'paper.ink', 'paper.onInk'],
      ['skeleton', 'paper.skeleton', 'paper.ink'],
    ] as const) {
      assert.ok(tile.includes(`${ground}: { fill: ${fill}, mark: ${mark} },`), `the ${ground} tile is not ${fill} with ${mark}`);
    }
    assert.doesNotMatch(tile, /textOn|sand/, 'the tile reads textOn or a sand ground palette.ts does not have');
    assert.match(tile, /name: BulkIconName;/, 'a Linear-only icon can stand on a tile');
    assert.match(tile, /\{\.\.\.decorative\}/, 'the tile is announced to a screen reader');
    assert.match(tile, /<Icon name=\{name\} variant="bulk" size=\{inner\} color=\{mark\} \/>/, 'the tile does not draw its icon Bulk in the mark colour');
  });
});
